import { describe, expect, it } from "vitest";

import {
  flattenRoutes,
  hostConditions,
  parseRoutes,
  renderHtaccess,
  toRewriteBranches,
} from "../vite-plugin-htaccess";

/** A stand-in for the module generated by `vue-router/vite`. */
const AUTO_ROUTES = `
import { defineComponent } from 'vue'
export const routes = [
  {
    path: '/',
    component: () => import('/src/layouts/default.vue'),
    children: [
      { path: '', name: '/', component: () => import('/src/pages/index.vue') },
      { path: 'ux-team', name: '/ux-team', component: () => import('/src/pages/ux-team.vue') },
      { path: 'solstice', component: () => import('/src/pages/solstice.vue'),
        children: [
          { path: 'secret', name: '/solstice/secret', component: () => import('/src/pages/solstice/secret.vue') },
        ],
      },
      { path: ':path(.*)', name: '/[...404]', component: () => import('/src/pages/[...404].vue') },
    ],
  },
]
`;

describe("parseRoutes", () => {
  it("extracts the route array without loading components", () => {
    const routes = parseRoutes(AUTO_ROUTES);

    expect(routes).toHaveLength(1);
    expect(routes[0].path).toBe("/");
    expect(routes[0].component).toBeNull();
  });

  it("throws when the routes array is missing", () => {
    expect(() => parseRoutes("export const nope = 1")).toThrow(
      /could not locate the routes array/,
    );
  });

  it("throws when the routes array is unterminated", () => {
    expect(() => parseRoutes("export const routes = [{ path: '/' }")).toThrow(
      /unterminated routes array/,
    );
  });
});

describe("flattenRoutes", () => {
  it("flattens nested children into absolute paths", () => {
    const paths = flattenRoutes(parseRoutes(AUTO_ROUTES));

    expect(paths).toContain("/");
    expect(paths).toContain("/ux-team");
    expect(paths).toContain("/solstice/secret");
  });

  it("skips records that render nothing", () => {
    const paths = flattenRoutes([
      { path: "/redirect-only", redirect: "/elsewhere" },
    ]);

    expect(paths).toEqual([]);
  });

  it("tolerates a missing route list", () => {
    expect(flattenRoutes(undefined)).toEqual([]);
  });
});

describe("toRewriteBranches", () => {
  it("drops the site root, which index.html already serves", () => {
    expect(toRewriteBranches(["/"])).toEqual([]);
  });

  it("drops dynamic routes, leaving them to the 404 handler", () => {
    expect(toRewriteBranches(["/:path(.*)", "/ux-team"])).toEqual(["ux-team"]);
  });

  it("drops excluded prefixes and their descendants", () => {
    const branches = toRewriteBranches(
      ["/ux-team", "/solstice/secret", "/solstice/secret/deeper", "/solstice"],
      ["/solstice/secret"],
    );

    expect(branches).toEqual(["solstice", "ux-team"]);
  });

  it("de-duplicates and sorts branches", () => {
    expect(toRewriteBranches(["/b", "/a", "/a/"])).toEqual(["a", "b"]);
  });

  it("escapes regex metacharacters in paths", () => {
    expect(toRewriteBranches(["/a.b"])).toEqual(["a\\.b"]);
  });
});

describe("hostConditions", () => {
  it("OR-joins every condition but the last", () => {
    expect(hostConditions(["a.test", "b.test"])).toEqual([
      "  RewriteCond %{HTTP_HOST} =a.test [NC,OR]",
      "  RewriteCond %{HTTP_HOST} =b.test [NC]",
    ]);
  });

  it("emits a single unflagged condition for one host", () => {
    expect(hostConditions(["only.test"])).toEqual([
      "  RewriteCond %{HTTP_HOST} =only.test [NC]",
    ]);
  });
});

describe("renderHtaccess", () => {
  it("rewrites known routes to the app shell under base", () => {
    const out = renderHtaccess(["ux-team"], "/ux/");

    expect(out).toContain("RewriteRule ^(ux-team)/?$ /ux/index.html [L]");
  });

  it("serves unknown paths as the shell with a real 404", () => {
    expect(renderHtaccess(["ux-team"], "/ux/")).toContain(
      "ErrorDocument 404 /ux/index.html",
    );
  });

  it("passes real files and directories through untouched", () => {
    const out = renderHtaccess(["ux-team"], "/ux/");

    expect(out).toContain("RewriteCond %{REQUEST_FILENAME} -f [OR]");
    expect(out).toContain("RewriteCond %{REQUEST_FILENAME} -d");
  });

  it("never matches anything when there are no routes", () => {
    expect(renderHtaccess([], "/ux/")).toContain("RewriteRule ^($^)/?$");
  });

  it("omits the masked-host block by default", () => {
    const out = renderHtaccess(["ux-team"], "/ux/");

    expect(out).not.toContain("HTTP_HOST");
    expect(out).not.toContain("RewriteRule ^ux/");
  });

  it("strips the base prefix on masked hosts", () => {
    const out = renderHtaccess(["ux-team"], "/ux/", {
      maskedHosts: ["uxdesign.uw.edu"],
    });

    expect(out).toContain("RewriteCond %{HTTP_HOST} =uxdesign.uw.edu [NC]");
    expect(out).toContain("RewriteRule ^ux/(.*)$ /$1 [L]");
  });

  it("orders the strip rule before the file passthrough", () => {
    const out = renderHtaccess(["ux-team"], "/ux/", {
      maskedHosts: ["uxdesign.uw.edu"],
    });

    expect(out.indexOf("RewriteRule ^ux/(.*)$")).toBeLessThan(
      out.indexOf("REQUEST_FILENAME"),
    );
  });

  it("skips the strip rule when the base is the site root", () => {
    const out = renderHtaccess(["ux-team"], "/", {
      maskedHosts: ["uxdesign.uw.edu"],
    });

    expect(out).not.toContain("HTTP_HOST");
    expect(out).toContain("ErrorDocument 404 /index.html");
  });

  it("emits the CORS header only when an origin is given", () => {
    expect(renderHtaccess(["ux-team"], "/ux/")).not.toContain("Header set");
    expect(
      renderHtaccess(["ux-team"], "/ux/", { allowOrigin: "https://x.test" }),
    ).toContain('Header set Access-Control-Allow-Origin "https://x.test"');
  });

  it("guards directives with the modules they need", () => {
    const out = renderHtaccess(["ux-team"], "/ux/", {
      allowOrigin: "https://x.test",
    });

    expect(out).toContain("<IfModule mod_rewrite.c>");
    expect(out).toContain("<IfModule mod_headers.c>");
  });

  it("avoids <If>, which requires AllowOverride All", () => {
    const out = renderHtaccess(["ux-team"], "/ux/", {
      maskedHosts: ["uxdesign.uw.edu"],
      allowOrigin: "https://x.test",
    });

    expect(out).not.toMatch(/<If\s/);
    expect(out).not.toContain("<Else>");
  });
});
